export const eventsToml = "# The stable events a plugin stage can follow (Epic 54, README §4.2, story 54.06 §6).\n#\n# A plugin never names a core stage: it names an event, and this file maps the event to\n# the core stage whose output means it. When a core stage is renamed or split, only this\n# file changes. tools/ci/tests/test_plugin_events.py fails when an event names a stage\n# that is not in the pipeline's GRAPH, and when an event is removed without a new plugin\n# API major.\n#\n# Fields:\n#   name      the event a manifest's [[stage.trigger]] names\n#   subject   the subject kind of the jobs it starts (a trigger's stage must match it)\n#   stage     the core stage whose changed output fires it (\"\" for schedule)\n#   map       the Edge map from that stage's subject to this subject (engine/graph.py)\n#   trigger   false: not a [[stage.trigger]] event ([[schedule]] only)\n#   since     the plugin API minor (1.x) that added it\n#\n# series.changed starts a season job: the engine forms series as seasons (detect), and\n# seasons_changed is the map that names the seasons a detect pass changed.\n\nschema = 1\n\n[[event]]\nname    = \"video.added\"\nsubject = \"video\"\nstage   = \"probe\"\nmap     = \"same\"\nsince   = \"1.0\"\n\n[[event]]\nname    = \"video.changed\"\nsubject = \"video\"\nstage   = \"content_hash\"\nmap     = \"same\"\nsince   = \"1.0\"\n\n[[event]]\nname    = \"audio.ready\"\nsubject = \"video\"\nstage   = \"extract\"\nmap     = \"same\"\nsince   = \"1.0\"\n\n[[event]]\nname    = \"transcript.ready\"\nsubject = \"video\"\nstage   = \"transcribe\"\nmap     = \"same\"\nsince   = \"1.0\"\n\n[[event]]\nname    = \"subtitles.ready\"\nsubject = \"video\"\nstage   = \"subtitle_gen\"\nmap     = \"same\"\nsince   = \"1.0\"\n\n[[event]]\nname    = \"thumbnails.ready\"\nsubject = \"video\"\nstage   = \"thumbnail\"\nmap     = \"same\"\nsince   = \"1.0\"\n\n[[event]]\nname    = \"metadata.changed\"\nsubject = \"video\"\nstage   = \"enrich\"\nmap     = \"same\"\nsince   = \"1.0\"\n\n[[event]]\nname    = \"series.changed\"\nsubject = \"season\"\nstage   = \"detect\"\nmap     = \"seasons_changed\"\nsince   = \"1.0\"\n\n[[event]]\nname    = \"library.scanned\"\nsubject = \"library\"\nstage   = \"scan\"\nmap     = \"same\"\nsince   = \"1.0\"\n\n[[event]]\nname    = \"schedule\"\nsubject = \"catalog\"\nstage   = \"\"\nmap     = \"catalog\"\ntrigger = false\nsince   = \"1.0\"\n";
